const base = pm.variables.get('baseURL').replace(/\/$/, '') + '/api';
const key = pm.variables.get('idem_key');
const maxBefore = Number(pm.variables.get('max_order_before') || 0);
const pick = (o, re) => { for (const k in (o || {})) if (re.test(k)) return o[k]; };
const parse = r => { try { return r.json(); } catch (e) { return null; } };
const idOf = o => { const b = (o && o.order) || o; return pick(b, /^orderid$/i) ?? pick(b, /^id$/i); };
const body = { customerId: 1, address: '12 Idempotency Street, Johannesburg', couponCode: '',
               items: [{ productId: 2, quantity: 1 }] };
 
pm.test('Request 1 creates the order (200/201)', () => pm.expect(pm.response.code).to.be.oneOf([200, 201]));
const firstId = idOf(parse(pm.response));
console.log('Original order id:', firstId, '| key:', key);
 
const send = cb => pm.sendRequest({
  url: base + '/orders', method: 'POST',
  header: { 'Content-Type': 'application/json', 'Idempotency-Key': key },
  body: { mode: 'raw', raw: JSON.stringify(body) }
}, (e, r) => cb(r ? r.code : null, r ? parse(r) : null));
 
const results = []; let done = 0;
const finish = () => {
  if (++done < 2) return;
  results.forEach((x, i) => {
    pm.test('Duplicate ' + (i + 1) + ': returns the original order or 409', () => {
      pm.expect(x.c).to.be.oneOf([200, 201, 409]);
      if (x.c !== 409) pm.expect(String(idOf(x.d))).to.eql(String(firstId));
    });
  });
 
 
  pm.sendRequest(base + '/orders?customerId=1', (e, r) => {
    const d = parse(r);
    const list = Array.isArray(d) ? d : (d && (d.orders || d.data)) || [];
    const created = list.filter(o => Number(pick(o, /^orderid$/i)) > maxBefore);
    console.log('New order ids since the test started:', created.map(o => pick(o, /^orderid$/i)));
    pm.test('Exactly one order exists for the key', () => pm.expect(created.length).to.eql(1));
  });
};
send((c, d) => { results[0] = { c, d }; finish(); });
send((c, d) => { results[1] = { c, d }; finish(); });

